            >
              {/* Rank number */}
              <div className="absolute -left-2 sm:-left-4 top-0 bottom-0 flex items-center z-10 pointer-events-none">
                <span
                  className="font-display text-7xl sm:text-8xl text-transparent leading-none"
                  style={{
                    WebkitTextStroke: '2px rgba(255,255,255,0.25)',
                  }}
                >
                  {item.rank}
                </span>
              </div>

              {/* Card */}
              <div
                className="relative ml-6 sm:ml-8 w-28 h-40 sm:w-36 sm:h-52 rounded-lg overflow-hidden transition-transform duration-300 hover:scale-105"
                style={{ background: item.color }}
              >
                <div className="absolute inset-0 poster-gradient" />
                <div className="absolute bottom-3 left-3 right-3">
                  <p className="text-sw-white font-semibold text-sm sm:text-base leading-tight">
                    {item.title}
                  </p>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Arrow control */}
        <button
          onClick={scrollRight}
          className="absolute right-2 sm:right-6 top-1/2 -translate-y-1/2 z-20 w-10 h-10 sm:w-12 sm:h-12 rounded-full bg-black/60 hover:bg-black/80 border border-sw-white/20 flex items-center justify-center text-sw-white transition-all duration-200 opacity-0 group-hover:opacity-100"
          aria-label="Scroll right"
        >
          <ChevronRight className="h-5 w-5 sm:h-6 sm:w-6" />
        </button>
      </div>
    </section>
  )
}

