import { useState } from 'react'
import { Plus, X } from 'lucide-react'
import { siteConfig } from '../config/site'

export default function FAQ() {
  const [openIndex, setOpenIndex] = useState<number | null>(null)

  const toggle = (index: number) => {
    setOpenIndex(openIndex === index ? null : index)
  }

  return (
    <section className="py-12 sm:py-20 bg-sw-black">
      <div className="mx-auto max-w-[1440px] px-4 sm:px-6 lg:px-12">
        <h2 className="font-display text-3xl sm:text-4xl tracking-wide text-sw-white mb-8 sm:mb-12">
          {siteConfig.faq.heading}
        </h2>

        <div className="max-w-4xl mx-auto space-y-2">
          {siteConfig.faq.items.map((item, index) => {
            const isOpen = openIndex === index
            return (
              <div
                key={index}
                className="bg-sw-dark rounded-lg overflow-hidden"
              >
                <button
                  onClick={() => toggle(index)}
                  className="w-full flex items-center justify-between px-5 sm:px-8 py-5 sm:py-6 text-left hover:bg-sw-gray/20 transition-colors duration-200"
                  aria-expanded={isOpen}
                >
                  <span className="text-sw-white text-base sm:text-lg font-medium pr-4">
                    {item.q}
                  </span>
                  {isOpen ? (
                    <X className="h-6 w-6 text-sw-white flex-shrink-0" />
                  ) : (
                    <Plus className="h-6 w-6 text-sw-white flex-shrink-0" />
                  )}
                </button>
                <div
                  className="overflow-hidden transition-all duration-300 ease-out"
                  style={{
                    maxHeight: isOpen ? '500px' : '0px',
                    opacity: isOpen ? 1 : 0,
                  }}
                >
                  <div className="px-5 sm:px-8 pb-5 sm:pb-6 text-sw-gray-light text-base sm:text-lg leading-relaxed">
                    {item.a}
                  </div>
                </div>
              </div>
            )
          })}
        </div>
      </div>
    </section>
  )
}

